import Grid from "@mui/material/Grid";
import Typography from "@mui/material/Typography";
import Box from "@mui/material/Box";
import { Card, CardContent, Button } from "@mui/material";
import DownloadOutlined from "@mui/icons-material/DownloadOutlined";
import NetworkCheckIcon from '@mui/icons-material/NetworkCheck';

const NetworkActivitySection = () => {
    return (
        <Box sx={{ py: 12, px: 2, bgcolor: "#FAFAF8" }} id="networkactivitysection">
            <Grid container spacing={6} justifyContent="center">
                {/* Network Activity */}
                <Grid item xs={12} md={4}>
                    <Card
                        sx={{
                            p: 4,
                            height: "100%",
                            borderRadius: "20px",
                            background: "linear-gradient(to bottom, #ffffff, #f5f5f5)",
                            border: "1px solid #D0E9EF",
                            boxShadow: "0px 8px 24px rgba(0,0,0,0.06)",
                            transition: "transform 0.3s ease",
                            "&:hover": {
                                transform: "translateY(-4px)",
                            },
                        }}
                    >
                        <CardContent sx={{ textAlign: "center" }}>
                            <Typography variant="h4" fontWeight="bold" mb={3} color="#2C3E50">
                                Network Activity
                            </Typography>

                            <NetworkCheckIcon sx={{ fontSize: 80, color: "#A97855", mb: 2 }} />

                            <Typography variant="body1" color="#666" sx={{ mb: 4, px: 2 }}>
                                Monitor real-time stats on Alkebuleum: block confirmations, transactions, and validator checkpoints.
                            </Typography>

                            <Button
                                href="https://explorer.alkebuleum.com"
                                target="_blank"
                                variant="outlined"
                                sx={{
                                    borderColor: "#A97855",
                                    color: "#A97855",
                                    px: 4,
                                    py: 1.5,
                                    fontWeight: "bold",
                                    textTransform: "none",
                                    borderRadius: "12px",
                                    "&:hover": {
                                        backgroundColor: "#f9d0ba",
                                        borderColor: "#f9d0ba",
                                        color: "#333",
                                    },
                                }}
                            >
                                Launch Block Explorer
                            </Button>
                        </CardContent>
                    </Card>
                </Grid>

                {/* Whitepaper */}
                <Grid item xs={12} md={4}>
                    <Card
                        sx={{
                            p: 4,
                            height: "100%",
                            borderRadius: "20px",
                            background: "linear-gradient(to bottom, #ffffff, #f5f5f5)",
                            border: "1px solid #D0E9EF",
                            boxShadow: "0px 8px 24px rgba(0,0,0,0.06)",
                            transition: "transform 0.3s ease",
                            "&:hover": {
                                transform: "translateY(-4px)",
                            },
                        }}
                    >
                        <CardContent sx={{ textAlign: "center" }}>
                            <Typography variant="h4" fontWeight="bold" mb={3} color="#2C3E50">
                                Whitepaper
                            </Typography>

                            <DownloadOutlined sx={{ fontSize: 80, color: "#A97855", mb: 2 }} />

                            <Typography variant="body1" color="#666" sx={{ mb: 4, px: 2 }}>
                                Learn how Alkebuleum empowers transparency and decentralization through African-built blockchain innovation.
                            </Typography>

                            <Button
                                href="/AlkebuleumWhitepaper.pdf"
                                target="_blank"
                                download
                                variant="outlined"
                                sx={{
                                    borderColor: "#A97855",
                                    color: "#A97855",
                                    px: 4,
                                    py: 1.5,
                                    fontWeight: "bold",
                                    textTransform: "none",
                                    borderRadius: "12px",
                                    "&:hover": {
                                        backgroundColor: "#f9d0ba",
                                        borderColor: "#f9d0ba",
                                        color: "#333",
                                    },
                                }}
                            >
                                Download Whitepaper
                            </Button>
                        </CardContent>
                    </Card>
                </Grid>

                {/* Vision Paper */}
                <Grid item xs={12} md={4}>
                    <Card
                        sx={{
                            p: 4,
                            height: "100%",
                            borderRadius: "20px",
                            background: "linear-gradient(to bottom, #ffffff, #f5f5f5)",
                            border: "1px solid #D0E9EF",
                            boxShadow: "0px 8px 24px rgba(0,0,0,0.06)",
                            transition: "transform 0.3s ease",
                            "&:hover": {
                                transform: "translateY(-4px)",
                            },
                        }}
                    >
                        <CardContent sx={{ textAlign: "center" }}>
                            <Typography variant="h4" fontWeight="bold" mb={3} color="#2C3E50">
                                Vision Paper
                            </Typography>

                            <DownloadOutlined sx={{ fontSize: 80, color: "#A97855", mb: 2 }} />

                            <Typography variant="body1" color="#666" sx={{ mb: 4, px: 2 }}>
                                Discover our long-term vision for digital trust, identity, and governance powered by the Alkebuleum ecosystem.
                            </Typography>

                            <Button
                                href="/AlkebuleumVisionpaper.pdf"
                                target="_blank"
                                download
                                variant="outlined"
                                sx={{
                                    borderColor: "#A97855",
                                    color: "#A97855",
                                    px: 4,
                                    py: 1.5,
                                    fontWeight: "bold",
                                    textTransform: "none",
                                    borderRadius: "12px",
                                    "&:hover": {
                                        backgroundColor: "#f9d0ba",
                                        borderColor: "#f9d0ba",
                                        color: "#333",
                                    },
                                }}
                            >
                                Download Vision Paper
                            </Button>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>
        </Box>
    );
};

export default NetworkActivitySection;
