import * as React from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { Box } from "@mui/material";
import Home from "./home";
import AcademyHomePage from "./Academy/AcademyHomePage";
import RewardsPage from "./getAKE/RewardsPage";
import JoinPage from "./JoinUs/JoinPage";
import CourseDetailPage from "./Academy/CourseDetailPage";

function Main() {
    return (
        <BrowserRouter basename="/">
            <Box>
                <Routes>
                    <Route exact path="/" element={<Home />} />
                    <Route path="/academy" element={<AcademyHomePage />} />
                    <Route path="/academy/course/:courseId" element={<CourseDetailPage />} />
                    <Route path="/rewards" element={<RewardsPage />} />
                    <Route path="/join" element={<JoinPage />} />
                </Routes>
            </Box>
        </BrowserRouter>
    );
}

export default Main;
