import React, { useState } from "react";
import { Link as RouterLink } from "react-router-dom";
import {
    Box,
    Container,
    Grid,
    Typography,
    Stack,
    Button,
    Drawer,
} from "@mui/material";
import TravelExploreIcon from "@mui/icons-material/TravelExplore";
import AppRegistrationIcon from "@mui/icons-material/AppRegistration";
import heroArt from "../../images/back.png";
import AccountBalanceWalletIcon from '@mui/icons-material/AccountBalanceWallet';

const HeroSection = () => {
    const [isDrawerOpen, setDrawerOpen] = useState(false);
    const toggleDrawer = (open) => () => setDrawerOpen(open);

    return (
        <Box id="herosection" sx={{ bgcolor: "#fff" }}>
            {/* Background Image on top */}
            <Box
                component="img"
                src={heroArt}
                alt="Hero Background"
                sx={{
                    width: "100%",
                    height: { xs: "300px", md: "500px" },
                    objectFit: "cover",
                    objectPosition: "center",
                }}
            />

            {/* Content Section */}
            <Container maxWidth="lg" sx={{ py: 8 }}>
                <Grid container spacing={6} justifyContent="center">
                    <Grid item xs={12} md={8}>
                        <Box textAlign="center">
                            <Typography variant="h3" fontWeight="bold" mb={3} color="#2C3E50">
                                Welcome to Alkebuleum
                            </Typography>

                            <Typography
                                variant="body1"
                                color="textSecondary"
                                sx={{ mb: 5, lineHeight: 1.8 }}
                            >
                                African blockchain network powering decentralized applications that address real-world challenges across governance, identity, finance, and transparency.
                            </Typography>

                            {/* Buttons */}
                            <Stack
                                direction={{ xs: "column", sm: "row" }}
                                spacing={2}
                                justifyContent="center"
                            >
                                {/* <Button
                                    href="https://amvault.net"
                                    target="_blank"
                                    variant="outlined"
                                    startIcon={<AccountBalanceWalletIcon />}
                                    sx={{
                                        borderColor: "#A97855",
                                        color: "#A97855",
                                        fontWeight: "bold",
                                        px: 4,
                                        py: 1.5,
                                        borderRadius: "12px",
                                        textTransform: "none",
                                        "&:hover": {
                                            backgroundColor: "#f9d0ba",
                                            borderColor: "#f9d0ba",
                                            color: "#2C3E50",
                                        },
                                    }}
                                >
                                    Create Account
                                </Button> */}
                                <Button
                                    href="https://chat.whatsapp.com/E90CmkC0n2J1SUV2PgCaTJ"
                                    target="_blank"
                                    variant="contained"
                                    startIcon={<AppRegistrationIcon />}
                                    sx={{
                                        backgroundColor: "#A97855",
                                        color: "#fff",
                                        fontWeight: "bold",
                                        px: 4,
                                        py: 1.5,
                                        borderRadius: "12px",
                                        textTransform: "none",
                                        "&:hover": {
                                            backgroundColor: "#8b6244",
                                        },
                                    }}
                                >
                                    Get Involve
                                </Button>
                            </Stack>
                        </Box>
                    </Grid>
                </Grid>
            </Container>

            {/* Drawer - AKE Info */}
            <Drawer
                anchor="bottom"
                open={isDrawerOpen}
                onClose={toggleDrawer(false)}
                sx={{
                    ".MuiDrawer-paper": {
                        borderTopLeftRadius: "20px",
                        borderTopRightRadius: "20px",
                        padding: 4,
                    },
                }}
            >
                <Box>
                    <Typography
                        variant="h5"
                        fontWeight="bold"
                        color="#A97855"
                        mb={2}
                    >
                        How to Get AKE Coin
                    </Typography>

                    <Typography variant="body1" color="textSecondary" mb={3}>
                        AKE is not for sale but can be earned through contributions to the ecosystem:
                    </Typography>

                    <ul style={{ color: "#555", paddingLeft: "1.2rem" }}>
                        <li>Engage in governance or community programs</li>
                        <li>Contribute development or educational resources</li>
                        <li>Support ecosystem projects through donations</li>
                    </ul>
                </Box>
            </Drawer>
        </Box>
    );
};

export default HeroSection;
