import * as React from "react";
import { styled } from "@mui/material/styles";
import ArrowForwardIosSharpIcon from "@mui/icons-material/ArrowForwardIosSharp";
import InfoIcon from "@mui/icons-material/Info";
import SecurityIcon from "@mui/icons-material/Security";
import StarIcon from "@mui/icons-material/Star";
import MuiAccordion from "@mui/material/Accordion";
import MuiAccordionSummary from "@mui/material/AccordionSummary";
import MuiAccordionDetails from "@mui/material/AccordionDetails";
import { Typography, Box, Grid } from "@mui/material";

// Styled accordion container
const Accordion = styled((props) => (
    <MuiAccordion disableGutters elevation={0} square {...props} />
))(({ theme }) => ({
    border: `1px solid ${theme.palette.divider}`,
    borderRadius: "8px",
    marginBottom: theme.spacing(2),
    "&:before": {
        display: "none",
    },
}));

const AccordionSummary = styled((props) => (
    <MuiAccordionSummary
        expandIcon={<ArrowForwardIosSharpIcon sx={{ fontSize: "0.9rem", color: "#A97855" }} />}
        {...props}
    />
))(({ theme }) => ({
    backgroundColor: "#f9f9f9",
    flexDirection: "row-reverse",
    borderRadius: "8px",
    "& .MuiAccordionSummary-expandIconWrapper.Mui-expanded": {
        transform: "rotate(90deg)",
    },
    "& .MuiAccordionSummary-content": {
        marginLeft: theme.spacing(1),
        fontWeight: 600,
        color: "#A97855",
    },
    "&:hover": {
        backgroundColor: "#f3e6dc",
    },
}));

const AccordionDetails = styled(MuiAccordionDetails)(({ theme }) => ({
    padding: theme.spacing(2),
    backgroundColor: "#fff",
    borderTop: "1px solid rgba(0, 0, 0, 0.1)",
    borderRadius: "8px",
    color: "#555",
}));

const FaqSection = () => {
    const [expanded, setExpanded] = React.useState("panel1");

    const handleChange = (panel) => (event, newExpanded) => {
        setExpanded(newExpanded ? panel : false);
    };

    return (
        <Box sx={{ py: 10, bgcolor: "#white", px: 3 }} id="faqsection">
            <Box textAlign="center" mb={6}>
                <Typography variant="h4" fontWeight="bold" color="#333">
                    Frequently Asked Questions
                </Typography>
                <Typography variant="body1" color="#666">
                    Get answers to the most common questions about the Alkebuleum Blockchain.
                </Typography>
            </Box>

            <Grid container spacing={3} justifyContent="center">
                <Grid item xs={12} md={8}>
                    {/* FAQ 1 */}
                    <Accordion expanded={expanded === "panel1"} onChange={handleChange("panel1")}>
                        <AccordionSummary>
                            <InfoIcon sx={{ mr: 1, color: "#A97855" }} />
                            <Typography>What is Alkebuleum Blockchain?</Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                            <Typography>
                                Alkebuleum is a next-gen blockchain built to solve real societal problems, especially in Africa.
                                <br /><br />
                                Key areas of focus:
                                <ul>
                                    <li>Combatting institutional corruption</li>
                                    <li>Improving economic access for communities</li>
                                    <li>Enabling transparent digital governance</li>
                                </ul>
                            </Typography>
                        </AccordionDetails>
                    </Accordion>

                    {/* FAQ 2 */}
                    <Accordion expanded={expanded === "panel2"} onChange={handleChange("panel2")}>
                        <AccordionSummary>
                            <SecurityIcon sx={{ mr: 1, color: "#A97855" }} />
                            <Typography>How does Alkebuleum ensure security?</Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                            <Typography>
                                We combine industry best practices and blockchain-native security including:
                                <ul>
                                    <li>End-to-end encryption</li>
                                    <li>Consensus verification (PoRA + zk)</li>
                                    <li>Decentralized identity with ZKIDs</li>
                                </ul>
                                Your data stays tamper-proof, transparent, and compliant.
                            </Typography>
                        </AccordionDetails>
                    </Accordion>

                    {/* FAQ 3 */}
                    <Accordion expanded={expanded === "panel3"} onChange={handleChange("panel3")}>
                        <AccordionSummary>
                            <StarIcon sx={{ mr: 1, color: "#A97855" }} />
                            <Typography>What makes Alkebuleum different?</Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                            <Typography>
                                Alkebuleum focuses on **impact over speculation**.
                                <br /><br />
                                What makes us unique:
                                <ul>
                                    <li>Purpose-built apps for Africa</li>
                                    <li>Low or zero gas fees for social utilities</li>
                                    <li>Earn tokens through verified contribution, not mining</li>
                                </ul>
                                <br />
                                <strong>
                                    → <a href="#howitworks" style={{ color: "#A97855" }}>Learn how it works</a>
                                </strong>
                            </Typography>
                        </AccordionDetails>
                    </Accordion>
                </Grid>
            </Grid>
        </Box>
    );
};

export default FaqSection;
