// src/pages/RewardsPage.jsx
import React, { useState } from "react";
import {
    Box,
    Container,
    Typography,
    TextField,
    Button,
    CircularProgress,
    Alert,
    Paper,
    Divider,
} from "@mui/material";

const RewardsPage = () => {
    const [zkid, setZkid] = useState("");
    const [wallet, setWallet] = useState("");
    const [loading, setLoading] = useState(false);
    const [rewardData, setRewardData] = useState(null);
    const [message, setMessage] = useState(null);
    const [error, setError] = useState(null);

    const checkReward = async () => {
        setLoading(true);
        setError(null);
        setRewardData(null);
        try {
            const res = await fetch(`https://node.alkebuleum.com/api/rewards/check?zkid=${zkid}`);
            const data = await res.json();
            if (!res.ok) throw new Error(data.error || "Failed to fetch rewards");
            setRewardData(data);
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const redeem = async () => {
        setLoading(true);
        setError(null);
        setMessage(null);
        try {
            const res = await fetch(`https://node.alkebuleum.com/api/rewards/redeem`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ zkid, walletAddress: wallet }),
            });
            const data = await res.json();
            if (!res.ok) throw new Error(data.error || "Redeem failed");
            setMessage(`Claim successful! TX Hash: ${data.txHash}`);
            setRewardData((prev) => ({ ...prev, pendingAKE: 0 }));
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Container maxWidth="sm" sx={{ py: 10 }}>
            <Typography variant="h4" fontWeight="bold" mb={2} color="#2C3E50">
                Claim Your AKE Rewards
            </Typography>

            <Typography variant="body1" color="textSecondary" mb={3}>
                Enter your ZkID to check your pending AKE rewards. If eligible, provide
                your wallet address to receive your reward.
            </Typography>

            <Paper sx={{ p: 3, borderRadius: 3 }}>
                <TextField
                    label="ZkID"
                    fullWidth
                    value={zkid}
                    onChange={(e) => setZkid(e.target.value)}
                    placeholder="zkid:ernest.947"
                    sx={{ mb: 2 }}
                />

                <Button variant="contained" fullWidth onClick={checkReward} disabled={loading}>
                    {loading ? <CircularProgress size={24} /> : "Check Rewards"}
                </Button>

                {rewardData && (
                    <Box mt={4}>
                        <Divider sx={{ mb: 2 }} />
                        <Typography variant="h6" color="#A97855">
                            Pending AKE: {rewardData.pendingAKE}
                        </Typography>
                        <Typography variant="body2" color="textSecondary" gutterBottom>
                            Total Earned: {rewardData.totalEarned}
                        </Typography>

                        {rewardData.pendingAKE > 0 && (
                            <>
                                <TextField
                                    label="Your Wallet Address"
                                    fullWidth
                                    value={wallet}
                                    onChange={(e) => setWallet(e.target.value)}
                                    sx={{ mt: 2 }}
                                />
                                <Button
                                    variant="outlined"
                                    fullWidth
                                    onClick={redeem}
                                    disabled={loading || !wallet}
                                    sx={{ mt: 2, borderColor: "#A97855", color: "#A97855" }}
                                >
                                    {loading ? <CircularProgress size={24} /> : "Redeem AKE"}
                                </Button>
                            </>
                        )}
                    </Box>
                )}

                {error && (
                    <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>
                )}
                {message && (
                    <Alert severity="success" sx={{ mt: 2 }}>{message}</Alert>
                )}
            </Paper>
        </Container>
    );
};

export default RewardsPage;
