import React, { useState, useEffect } from "react";
import {
    Box,
    Container,
    Typography,
    TextField,
    Button,
    Grid,
    Card,
    CardContent,
    CardActions,
} from "@mui/material";
import { Link as RouterLink } from "react-router-dom";
import { collection, getDocs, doc, getDoc } from "firebase/firestore";
import { db } from "../../firebase";

export default function AcademyHomePage() {
    const [alias, setAlias] = useState("");
    const [userZkid, setUserZkid] = useState(null);
    const [error, setError] = useState("");
    const [courses, setCourses] = useState([]);

    const fetchCourses = async () => {
        const snap = await getDocs(collection(db, "courses"));
        setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    };

    const handleLogin = async () => {
        const trimmed = alias.trim().toLowerCase();
        if (!trimmed) return;

        const fullZkid = `zkid:${trimmed}`;
        const zkRef = doc(db, "zkids", fullZkid);
        const zkSnap = await getDoc(zkRef);

        if (zkSnap.exists()) {
            setUserZkid(fullZkid);
            setError("");
            fetchCourses();
        } else {
            setError("ZKID not found. Please check your alias.");
        }
    };

    const handleLogout = () => {
        setUserZkid(null);
        setAlias("");
        setError("");
    };

    if (!userZkid) {
        return (
            <Box
                sx={{
                    py: 12,
                    minHeight: "100vh",
                    bgcolor: "#2C3E50",
                    color: "#fff",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    alignItems: "center",
                    textAlign: "center",
                }}
            >
                <Container maxWidth="xs">
                    <Typography variant="h4" fontWeight="bold" mb={3}>
                        Enter Your ZKID Alias
                    </Typography>
                    <TextField
                        label="Alias (e.g. ernesto.lr)"
                        fullWidth
                        value={alias}
                        onChange={(e) => setAlias(e.target.value)}
                        error={!!error}
                        helperText={error}
                        sx={{
                            mb: 3,
                            input: { color: "#fff" },
                            "& .MuiInputLabel-root": { color: "#ccc" },
                            "& .MuiOutlinedInput-root": {
                                "& fieldset": { borderColor: "#f9d0ba" },
                                "&:hover fieldset": { borderColor: "#fff" },
                                "&.Mui-focused fieldset": { borderColor: "#f9d0ba" },
                            },
                        }}
                    />
                    <Button
                        variant="contained"
                        fullWidth
                        onClick={handleLogin}
                        disabled={!alias.trim()}
                        sx={{
                            backgroundColor: "#f9d0ba",
                            color: "#2C3E50",
                            fontWeight: "bold",
                            textTransform: "none",
                            "&:hover": {
                                backgroundColor: "#ffffff",
                                color: "#2C3E50",
                            },
                        }}
                    >
                        Login
                    </Button>
                </Container>
            </Box>
        );
    }

    return (
        <Box component="section" sx={{ py: 10, bgcolor: "#FAFAF8", minHeight: "100vh" }}>
            <Container maxWidth="lg">
                <Box textAlign="center" mb={8}>
                    <Typography variant="h5" color="#A97855" fontWeight="bold" mb={1}>
                        🎓 Welcome, {userZkid}
                    </Typography>
                    <Button
                        onClick={handleLogout}
                        variant="outlined"
                        sx={{
                            mt: 2,
                            borderColor: "#A97855",
                            color: "#A97855",
                            fontWeight: "bold",
                            textTransform: "none",
                            "&:hover": {
                                backgroundColor: "#f9d0ba",
                                borderColor: "#f9d0ba",
                                color: "#333",
                            },
                        }}
                    >
                        Log Out
                    </Button>
                </Box>

                {/* Courses */}
                <Grid container spacing={4}>
                    {courses.map((course) => (
                        <Grid key={course.id} item xs={12} sm={6} md={4}>
                            <Card
                                elevation={0}
                                sx={{
                                    border: "1px solid #D0E9EF",
                                    borderRadius: "16px",
                                    backgroundColor: "#fff",
                                    display: "flex",
                                    flexDirection: "column",
                                    height: "100%",
                                    justifyContent: "space-between",
                                    p: 2,
                                    transition: "transform 0.3s ease, box-shadow 0.3s ease",
                                    "&:hover": {
                                        transform: "translateY(-6px)",
                                        boxShadow: "0px 8px 20px rgba(0, 0, 0, 0.08)",
                                    },
                                }}
                            >
                                <CardContent>
                                    <Typography variant="h6" fontWeight="bold" gutterBottom>
                                        {course.title}
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary">
                                        {course.description}
                                    </Typography>
                                </CardContent>
                                <CardActions>
                                    {course.status === "active" ? (
                                        <Button
                                            component={RouterLink}
                                            to={`/academy/course/${course.courseSlug}?zkid=${userZkid}`}
                                            variant="outlined"
                                            fullWidth
                                            sx={{
                                                textTransform: "none",
                                                borderColor: "#A97855",
                                                color: "#A97855",
                                                fontWeight: "bold",
                                                "&:hover": {
                                                    backgroundColor: "#f9d0ba",
                                                    borderColor: "#f9d0ba",
                                                    color: "#333",
                                                },
                                            }}
                                        >
                                            View Course
                                        </Button>
                                    ) : (
                                        <Button disabled variant="outlined" fullWidth>
                                            Coming Soon
                                        </Button>
                                    )}
                                </CardActions>
                            </Card>
                        </Grid>
                    ))}
                </Grid>

                {/* Back to Home */}
                <Box textAlign="center" mt={10}>
                    <Button
                        component={RouterLink}
                        to="/"
                        variant="contained"
                        sx={{
                            backgroundColor: "#A97855",
                            color: "#fff",
                            fontWeight: "bold",
                            textTransform: "none",
                            px: 5,
                            py: 1.5,
                            borderRadius: "12px",
                            "&:hover": {
                                backgroundColor: "#f9d0ba",
                                color: "#333",
                            },
                        }}
                    >
                        ← Back to Alkebuleum Home
                    </Button>
                </Box>
            </Container>
        </Box>
    );
}
