import Grid from "@mui/material/Grid";
import Typography from "@mui/material/Typography";
import Box from "@mui/material/Box";
import Container from "@mui/material/Container";
import { Link } from "@mui/material";
import LocationOn from "@mui/icons-material/LocationOn";
import LocalPhone from "@mui/icons-material/LocalPhone";
import Email from "@mui/icons-material/Email";
import Twitter from "@mui/icons-material/Twitter";
import Facebook from "@mui/icons-material/Facebook";
import Instagram from "@mui/icons-material/Instagram";
import Telegram from "@mui/icons-material/Telegram";
import { FaDiscord } from "react-icons/fa";

const Footer = () => {
    return (
        <Box sx={{ bgcolor: "#f5f5f5", color: "#333", pt: 8, pb: 4 }}>
            <Container maxWidth="lg">
                <Grid container spacing={6}>
                    {/* Column 1: Brand/Mission */}
                    <Grid item xs={12} md={4}>
                        <Typography variant="h6" fontWeight="bold" sx={{ mb: 2 }}>
                            Alkebuleum
                        </Typography>
                        <Typography variant="body2" sx={{ lineHeight: 1.8 }}>
                            A decentralized network for Africa and the diaspora. Powered by blockchain, governed by the people. Join us in building transparent institutions and economic opportunity.
                        </Typography>
                    </Grid>

                    {/* Column 2: Contact + Links */}
                    <Grid item xs={12} md={4}>
                        <Typography variant="h6" fontWeight="bold" sx={{ mb: 2 }}>
                            Contact
                        </Typography>
                        <Box sx={{ display: "flex", alignItems: "center", mb: 1 }}>
                            <LocationOn sx={{ color: "#A97855", mr: 1 }} />
                            <Typography variant="body2">Decentralized</Typography>
                        </Box>
                        <Box sx={{ display: "flex", alignItems: "center", mb: 1 }}>
                            <LocalPhone sx={{ color: "#A97855", mr: 1 }} />
                            <Typography variant="body2">+1 512 710 9124</Typography>
                        </Box>
                        <Box sx={{ display: "flex", alignItems: "center", mb: 1 }}>
                            <Email sx={{ color: "#A97855", mr: 1 }} />
                            <Typography variant="body2">info@alkebuleum.org</Typography>
                        </Box>
                        <Box mt={2}>
                            <Link href="#" sx={{ mr: 2, fontSize: 14, color: "#333", "&:hover": { textDecoration: "underline" } }}>
                                Terms
                            </Link>
                            <Link href="#" sx={{ fontSize: 14, color: "#333", "&:hover": { textDecoration: "underline" } }}>
                                Privacy
                            </Link>
                        </Box>
                    </Grid>

                    {/* Column 3: Social Icons */}
                    <Grid item xs={12} md={4}>
                        <Typography variant="h6" fontWeight="bold" sx={{ mb: 2 }}>
                            Connect with Us
                        </Typography>
                        <Box sx={{ display: "flex", gap: 2, flexWrap: "wrap" }}>
                            <Link href="https://twitter.com/alkebuleum" target="_blank" sx={socialIconStyle("#1DA1F2")}>
                                <Twitter sx={{ fontSize: 24 }} />
                            </Link>
                            <Link href="https://facebook.com/alkebuleum" target="_blank" sx={socialIconStyle("#4267B2")}>
                                <Facebook sx={{ fontSize: 24 }} />
                            </Link>
                            <Link href="https://instagram.com/alkebuleum" target="_blank" sx={socialIconStyle("#E1306C")}>
                                <Instagram sx={{ fontSize: 24 }} />
                            </Link>
                            <Link href="https://discord.gg/vmUY6mXG" target="_blank" sx={socialIconStyle("#7289DA")}>
                                <FaDiscord style={{ fontSize: 24 }} />
                            </Link>
                            <Link href="https://t.me/alkebuleum" target="_blank" sx={socialIconStyle("#0088CC")}>
                                <Telegram sx={{ fontSize: 24 }} />
                            </Link>
                        </Box>
                    </Grid>
                </Grid>

                {/* Bottom Row */}
                <Box mt={6} textAlign="center">
                    <Typography variant="body2" color="#777">
                        © {new Date().getFullYear()} Alkebuleum. All rights reserved.
                    </Typography>
                </Box>
            </Container>
        </Box>
    );
};

// Reusable style for social icons
const socialIconStyle = (hoverColor) => ({
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    width: 36,
    height: 36,
    borderRadius: "50%",
    backgroundColor: "#f1f1f1",
    color: "#A97855",
    transition: "0.3s",
    "&:hover": {
        backgroundColor: hoverColor,
        color: "#fff",
    },
});

export default Footer;
