import React from "react";
import {
    Box,
    Typography,
    Container,
    Grid,
    Card,
    CardContent,
    Button
} from "@mui/material";
import TravelExploreIcon from "@mui/icons-material/TravelExplore";

const activeDAOs = [
    {
        country: "Liberia",
        description: "The first DAO launched under the Alkebuleum banner, advocating blockchain as a tool against corruption in Liberia.",
        link: "https://forms.gle/dcKWHCbzhXjMuNZJ9" // Example join link (Telegram, Forum, etc.)
    }
];

const JoinPage = () => {
    return (
        <Box sx={{ py: 10, bgcolor: "#fefefe" }}>
            <Container maxWidth="md">
                <Typography variant="h4" fontWeight="bold" color="#2C3E50" mb={5} textAlign="center">
                    <TravelExploreIcon sx={{ fontSize: 40, verticalAlign: "middle", mr: 1 }} />
                    Join Your Country DAO
                </Typography>

                <Grid container spacing={4}>
                    {activeDAOs.map((dao, index) => (
                        <Grid item xs={12} sm={6} key={index}>
                            <Card
                                sx={{
                                    borderRadius: 3,
                                    boxShadow: "0 6px 20px rgba(0,0,0,0.05)",
                                }}
                            >
                                <CardContent>
                                    <Typography variant="h6" fontWeight="bold" mb={1}>
                                        {dao.country}
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary" mb={2}>
                                        {dao.description}
                                    </Typography>
                                    <Button
                                        href={dao.link}
                                        target="_blank"
                                        variant="outlined"
                                        sx={{
                                            borderColor: "#A97855",
                                            color: "#A97855",
                                            textTransform: "none",
                                            "&:hover": {
                                                backgroundColor: "#f9d0ba",
                                                borderColor: "#f9d0ba",
                                                color: "#333",
                                            }
                                        }}
                                    >
                                        Join Group
                                    </Button>
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                </Grid>

                <Box mt={6} textAlign="center">
                    <Typography variant="body1" color="text.secondary" mb={2}>
                        Don’t see your country listed?
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                        Contact us at <strong>info@alkebuleum.org</strong> to start a DAO in your country and advocate for blockchain as a tool to fight corruption across Africa.
                    </Typography>
                </Box>
            </Container>
        </Box>
    );
};

export default JoinPage;
