import React, { useState } from "react";
import {
    Container,
    Grid,
    Box,
    Typography,
    Card,
    Button,
    Drawer,
    useTheme,
} from "@mui/material";
import SecurityIcon from "@mui/icons-material/Security";
import HowToRegIcon from "@mui/icons-material/HowToReg";
import ListAltIcon from "@mui/icons-material/ListAlt";
import VerifiedUserIcon from "@mui/icons-material/VerifiedUser";
import GavelIcon from "@mui/icons-material/Gavel";
import AccountBalanceIcon from "@mui/icons-material/AccountBalance";
import BusinessCenterIcon from "@mui/icons-material/BusinessCenter";
import GroupIcon from "@mui/icons-material/Group";
import LocalShippingIcon from "@mui/icons-material/LocalShipping";
import SchoolIcon from "@mui/icons-material/School";

const allSolutions = [
    { title: "Anti-Corruption Ledger", description: "Immutable audit trails of government spending, procurement, and contracts—eliminating back-doors.", icon: SecurityIcon },
    { title: "Asset Ownership Registry", description: "Tamper-proof title registry for land, vehicles, and IP to resolve ownership disputes.", icon: HowToRegIcon },
    { title: "Transparent Auditing", description: "Real-time financial and operational audits, visible to regulators and citizens alike.", icon: ListAltIcon },
    { title: "Secure Identity Verification", description: "Decentralized IDs (DIDs) for institutions and individuals—no single point of failure.", icon: VerifiedUserIcon },
    { title: "Smart Contract Enforcement", description: "Self-executing legal agreements (land leases, service contracts) that enforce terms automatically.", icon: GavelIcon },
    { title: "Transparent Voting", description: "Decentralized e-voting for boards or public referenda with end-to-end verifiability.", icon: AccountBalanceIcon },
    { title: "Resource Allocation", description: "Track & allocate resources within organizations with full transparency.", icon: BusinessCenterIcon },
    { title: "Community Collaboration", description: "Decentralized project workspaces for NGOs, cooperatives, and civic groups.", icon: GroupIcon },
    { title: "Supply Chain Tracking", description: "End-to-end provenance for goods, deterring fraud and counterfeits.", icon: LocalShippingIcon },
    { title: "Education Grants Distribution", description: "Automated scholarships & grants payout with on-chain proof of use.", icon: SchoolIcon },
];

export default function FeaturesSection() {
    const theme = useTheme();
    const [drawerOpen, setDrawerOpen] = useState(false);
    const preview = allSolutions.slice(0, 4);

    const toggleDrawer = (open) => () => setDrawerOpen(open);

    const renderCard = ({ title, description, icon: Icon }, idx) => (
        <Card
            key={idx}
            elevation={0}
            sx={{
                p: 4,
                borderRadius: 4,
                backgroundColor: "#ffffff",
                border: "1px solid #D0E9EF",
                textAlign: "center",
                height: "100%",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "space-between",
                transition: "transform 0.3s ease, box-shadow 0.3s ease",
                "&:hover": {
                    transform: "translateY(-6px)",
                    boxShadow: "0px 10px 24px rgba(0,0,0,0.06)",
                },
            }}
        >
            <Box mb={3}>
                <Icon sx={{ fontSize: 48, color: "#A97855" }} />
            </Box>
            <Typography variant="h6" fontWeight="bold" mb={1}>
                {title}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.7 }}>
                {description}
            </Typography>
        </Card>
    );

    return (
        <Box
            component="section"
            id="featuressection"
            sx={{
                py: 14,
                background: "linear-gradient(180deg, #FAFAF8 0%, #F2F2F2 100%)",
                position: "relative",
                overflow: "hidden",
            }}
        >
            <Container maxWidth="lg">
                <Grid container spacing={8} alignItems="center">
                    {/* Text Section */}
                    <Grid item xs={12} md={5}>
                        <Box textAlign={{ xs: "center", md: "left" }}>
                            <Box
                                sx={{
                                    backgroundColor: "rgba(208,233,239,0.4)",
                                    color: "#7BA6AC",
                                    px: 3,
                                    py: 0.5,
                                    borderRadius: "20px",
                                    fontSize: "13px",
                                    textTransform: "uppercase",
                                    display: "inline-block",
                                    mb: 2,
                                    fontWeight: "bold",
                                }}
                            >
                                Solutions
                            </Box>

                            <Typography variant="h4" fontWeight="bold" mb={3} color="#2C3E50">
                                Blockchain Solutions for African Institutions
                            </Typography>

                            <Typography
                                variant="body1"
                                color="textSecondary"
                                sx={{ mb: 5, lineHeight: 1.8 }}
                            >
                                From audit trails to registries, Alkebuleum equips governments,
                                NGOs, and civic institutions with secure, transparent, decentralized tools.
                            </Typography>

                            <Button
                                onClick={toggleDrawer(true)}
                                variant="contained"
                                sx={{
                                    backgroundColor: "#A97855",
                                    color: "#fff",
                                    px: 5,
                                    py: 1.6,
                                    fontSize: "16px",
                                    borderRadius: "12px",
                                    textTransform: "none",
                                    fontWeight: "bold",
                                    "&:hover": {
                                        backgroundColor: "#f9d0ba",
                                        color: "#2C3E50",
                                    },
                                }}
                            >
                                Explore All Solutions
                            </Button>
                        </Box>
                    </Grid>

                    {/* Card Section */}
                    <Grid item xs={12} md={7}>
                        <Grid container spacing={4}>
                            {preview.map((solution, idx) => (
                                <Grid item xs={12} sm={6} key={idx}>
                                    {renderCard(solution, idx)}
                                </Grid>
                            ))}
                        </Grid>
                    </Grid>
                </Grid>
            </Container>

            {/* Drawer - All Solutions */}
            <Drawer
                anchor="bottom"
                open={drawerOpen}
                onClose={toggleDrawer(false)}
                sx={{
                    ".MuiDrawer-paper": {
                        borderTopLeftRadius: 20,
                        borderTopRightRadius: 20,
                        padding: 4,
                        backgroundColor: "#fff",
                    },
                }}
            >
                <Container>
                    <Box textAlign="center" mb={3}>
                        <Typography variant="h5" fontWeight="bold" color="#A97855" mb={1}>
                            All Solutions
                        </Typography>
                        <Typography variant="body2" color="text.secondary" mb={3}>
                            Discover how blockchain can transform African governance and transparency.
                        </Typography>

                        <Button
                            onClick={toggleDrawer(false)}
                            variant="outlined"
                            sx={{
                                color: "#A97855",
                                borderColor: "#A97855",
                                borderRadius: "999px",
                                px: 4,
                                py: 1.2,
                                fontWeight: "bold",
                                textTransform: "none",
                                "&:hover": {
                                    backgroundColor: "#f9d0ba",
                                    borderColor: "#f9d0ba",
                                    color: "#333",
                                },
                            }}
                        >
                            Close
                        </Button>
                    </Box>

                    <Grid container spacing={4}>
                        {allSolutions.map((solution, idx) => (
                            <Grid item xs={12} sm={6} md={4} key={idx}>
                                {renderCard(solution, idx)}
                            </Grid>
                        ))}
                    </Grid>
                </Container>
            </Drawer>
        </Box>
    );
}
