import React, { useState, useEffect } from "react";
import {
    Box,
    Container,
    Typography,
    Button,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    LinearProgress,
    Grid,
    Card,
    CardContent,
} from "@mui/material";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import { useParams, useLocation, Link as RouterLink } from "react-router-dom";
import { db } from "../../firebase";
import {
    collection,
    query,
    where,
    getDocs,
    doc,
    setDoc,
    getDoc,
    updateDoc,
    arrayUnion,
} from "firebase/firestore";

export default function CourseDetailPage() {
    const { courseId } = useParams();
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const zkid = queryParams.get("zkid");

    const [course, setCourse] = useState(null);
    const [enrollment, setEnrollment] = useState(null);
    const [progress, setProgress] = useState(0);

    useEffect(() => {
        if (courseId && zkid) {
            fetchCourse();
            fetchEnrollment();
        }
    }, [courseId, zkid]);

    const fetchCourse = async () => {
        const q = query(collection(db, "courses"), where("courseSlug", "==", courseId));
        const snap = await getDocs(q);
        if (!snap.empty) {
            setCourse(snap.docs[0].data());
        } else {
            console.error("Course not found:", courseId);
        }
    };

    const fetchEnrollment = async () => {
        const enrollmentId = `${zkid}_${courseId}`;
        const ref = doc(db, "course_enrollments", enrollmentId);
        const snap = await getDoc(ref);
        if (snap.exists()) {
            const data = snap.data();
            setEnrollment(data);
            setProgress(data.progress || 0);
        }
    };

    const handleStartCourse = async () => {
        const enrollmentId = `${zkid}_${courseId}`;
        await setDoc(doc(db, "course_enrollments", enrollmentId), {
            zkid,
            courseId,
            progress: 0,
            status: "in progress",
            quizResults: {},
            completedModules: [],
        });
        fetchEnrollment();
    };

    const handleMarkModuleComplete = async (idx) => {
        const enrollmentId = `${zkid}_${courseId}`;
        const docRef = doc(db, "course_enrollments", enrollmentId);
        const total = course.modules.length;
        const newProgress = Math.min(100, Math.round(((idx + 1) / total) * 100));
        await updateDoc(docRef, {
            progress: newProgress,
            completedModules: arrayUnion(idx),
        });
        fetchEnrollment();
    };

    if (!course) {
        return (
            <Container sx={{ py: 10 }}>
                <Typography variant="h4" textAlign="center">
                    Loading Course...
                </Typography>
            </Container>
        );
    }

    return (
        <Box>
            {/* Hero Section */}
            <Box
                sx={{
                    minHeight: { xs: "auto", md: "60vh" },
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    alignItems: "center",
                    backgroundColor: "#2C3E50",
                    color: "#fff",
                    textAlign: "center",
                    px: 2,
                    pt: 12,
                    pb: 8,
                }}
            >
                <Typography variant="h3" fontWeight="bold" gutterBottom>
                    {course.title}
                </Typography>
                <Typography
                    variant="h6"
                    sx={{
                        mb: 4,
                        maxWidth: 600,
                        mx: "auto",
                        color: "#D0D0D0",
                    }}
                >
                    {course.description}
                </Typography>

                {enrollment ? (
                    <Box sx={{ width: { xs: "90%", md: "50%" }, mt: 2 }}>
                        <Typography variant="body2" mb={1}>
                            Progress: {progress}%
                        </Typography>
                        <LinearProgress variant="determinate" value={progress} />
                    </Box>
                ) : (
                    <Button
                        variant="contained"
                        onClick={handleStartCourse}
                        sx={{
                            mt: 4,
                            backgroundColor: "#f9d0ba",
                            color: "#2C3E50",
                            fontWeight: "bold",
                            textTransform: "none",
                            px: 4,
                            py: 1.5,
                            borderRadius: "10px",
                            "&:hover": {
                                backgroundColor: "#fff",
                                color: "#2C3E50",
                            },
                        }}
                    >
                        Start Course
                    </Button>
                )}
            </Box>

            {/* Snapshot */}
            <Container sx={{ py: 8 }}>
                <Grid container spacing={4} justifyContent="center">
                    <Grid item xs={12} sm={4}>
                        <Card
                            elevation={0}
                            sx={{
                                border: "1px solid #D0E9EF",
                                borderRadius: "16px",
                                backgroundColor: "#fff",
                                textAlign: "center",
                                height: "100%",
                                p: 3,
                            }}
                        >
                            <CardContent>
                                <Typography variant="h6" fontWeight="bold" gutterBottom>
                                    {course.level || "Beginner"}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    Level
                                </Typography>
                            </CardContent>
                        </Card>
                    </Grid>

                    <Grid item xs={12} sm={4}>
                        <Card
                            elevation={0}
                            sx={{
                                border: "1px solid #D0E9EF",
                                borderRadius: "16px",
                                backgroundColor: "#fff",
                                textAlign: "center",
                                height: "100%",
                                p: 3,
                            }}
                        >
                            <CardContent>
                                <Typography variant="h6" fontWeight="bold" gutterBottom>
                                    {course.modules?.length || 0} Modules
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    Lessons
                                </Typography>
                            </CardContent>
                        </Card>
                    </Grid>
                </Grid>
            </Container>

            {/* Curriculum */}
            <Container sx={{ py: 8 }}>
                <Typography variant="h4" fontWeight="bold" textAlign="center" mb={6}>
                    Curriculum
                </Typography>

                {course.modules?.map((mod, idx) => {
                    const done = enrollment?.completedModules?.includes(idx);
                    return (
                        <Accordion
                            key={idx}
                            sx={{
                                mb: 2,
                                borderRadius: "8px",
                                backgroundColor: "#FAFAF8",
                                boxShadow: "none",
                                "&.Mui-expanded": {
                                    backgroundColor: "#ffffff",
                                    boxShadow: "0px 8px 20px rgba(0, 0, 0, 0.06)",
                                },
                            }}
                        >
                            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                                <Typography fontWeight="bold">{mod.title}</Typography>
                            </AccordionSummary>
                            <AccordionDetails>
                                <Box
                                    component="iframe"
                                    src={mod.videoUrl}
                                    width="100%"
                                    height={300}
                                    sx={{ borderRadius: 2, mb: 2 }}
                                    title={mod.title}
                                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                    allowFullScreen
                                />
                                <Box textAlign="right">
                                    {done ? (
                                        <Button
                                            variant="contained"
                                            startIcon={<CheckCircleIcon />}
                                            disabled
                                            sx={{
                                                backgroundColor: "#A97855",
                                                textTransform: "none",
                                                fontWeight: "bold",
                                                color: "#fff",
                                                px: 3,
                                                py: 1,
                                                borderRadius: "10px",
                                            }}
                                        >
                                            Completed
                                        </Button>
                                    ) : (
                                        <Button
                                            variant="outlined"
                                            onClick={() => handleMarkModuleComplete(idx)}
                                            sx={{
                                                textTransform: "none",
                                                fontWeight: "bold",
                                                borderColor: "#A97855",
                                                color: "#A97855",
                                                "&:hover": {
                                                    backgroundColor: "#f9d0ba",
                                                    borderColor: "#f9d0ba",
                                                    color: "#333",
                                                },
                                            }}
                                        >
                                            Mark Module {idx + 1} as Completed
                                        </Button>
                                    )}
                                </Box>
                            </AccordionDetails>
                        </Accordion>
                    );
                })}
            </Container>

            {/* Exit to Home */}
            <Box textAlign="center" py={8}>
                <Button
                    component={RouterLink}
                    to="/"
                    variant="contained"
                    sx={{
                        backgroundColor: "#A97855",
                        color: "#fff",
                        fontWeight: "bold",
                        textTransform: "none",
                        px: 5,
                        py: 1.5,
                        borderRadius: "12px",
                        "&:hover": {
                            backgroundColor: "#f9d0ba",
                            color: "#333",
                        },
                    }}
                >
                    Exit to Home
                </Button>
            </Box>
        </Box>
    );
}
