import React from "react";
import Grid from "@mui/material/Grid";
import Typography from "@mui/material/Typography";
import Box from "@mui/material/Box";
import { Button, Container, Chip, LinearProgress, Stack, Card, CardContent, Avatar } from "@mui/material";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";

const BRAND_PRIMARY = "#A97855";     // brown
const BRAND_DARK = "#2C3E50";
const BRAND_BLUE = "#7BA6AC";        // your blue ribbon tone

/** Data */
const milestones = [
    { date: "Jun 28, 2025", title: "Afina Testnet Live", desc: "Network operational; validators online; dev onboarding.", state: "done" },
    { date: "Jul–Dec 2025", title: "Developer Buildout", desc: "amVault • uGov • JollofSwap • OpenWork in active development.", state: "active" },
    { date: "Oct–Dec 2025", title: "RPU Rewards Window", desc: "Earn Reputation (RPU) on Afina; RPUs migrate to mainnet.", state: "active" },
    { date: "Jan–Feb 2026", title: "Readiness & Migration", desc: "Audits, failover drills, migration rehearsals.", state: "upcoming" },
    { date: "Mar 2026", title: "Mainnet Launch", desc: "AKE activates; RPUs honored; apps go live.", state: "upcoming" },
];

/** Core Development progress */
const coreDev = [
    { name: "Explorer", sub: "Public block explorer", pct: 100 },
    // { name: "Testnet + Faucet", sub: "Afina testnet & onboarding", pct: 60 },
    // { name: "Network Dashboard", sub: "Validators, blocks, token metrics", pct: 35 },
    { name: "Security & Monitoring", sub: "Alerts, audits, failover, policies", pct: 50 },
    { name: "Developer/Founders Tools", sub: "SDKs, docs, templates, CLI", pct: 25 },
    { name: "Governance Tools", sub: "DAO registry & on-chain config", pct: 70 },
];

/** Alkebuleum-built apps (add Aketech here if you want it shown with an icon) */
const alkebApps = [
    { name: "AmVault", sub: "Identity vault & wallet", pct: 72 },
    { name: "UGov", sub: "DAO creation & governance", pct: 80 },
    { name: "Jengo", sub: "Project & freelancer platform", pct: 5 },
    // { name: "Aketech", sub: "Core utilities app", pct: 15 }, // ← example
];

/** Independent ecosystem apps */
const ecosystemApps = [
    {
        name: "Welcome Home",
        sub: "Housing & community portal",
        href: "https://www.facebook.com/officialblackwallstreet/posts/sharufa-walker-is-on-a-mission-to-help-the-diaspora-reclaim-its-connection-to-th/1135756028567788/",
    },
    {
        name: "Digital Liberia Exchange",
        sub: "Digital asset marketplace",
        href: "http://exchange.digitalliberia.com",
    },
];

function StatPill({ label }) {
    return (
        <Box sx={{ px: 1.5, py: 0.75, borderRadius: 999, bgcolor: "rgba(0,0,0,0.04)", color: "#475569", fontSize: 12, fontWeight: 700, display: "inline-block" }}>
            {label}
        </Box>
    );
}

/** Progress row now supports optional avatar + 100%->blue bar */
function ProgressRow({ name, sub, pct, showAvatar }) {
    const barColor = pct === 100 ? BRAND_BLUE : BRAND_PRIMARY;
    return (
        <Box sx={{ mb: 2 }}>
            <Stack direction="row" justifyContent="space-between" alignItems="center" spacing={1.25}>
                <Stack direction="row" alignItems="center" spacing={1}>
                    {showAvatar && (
                        <Avatar
                            sx={{
                                width: 28, height: 28, bgcolor: "rgba(0,0,0,0.06)",
                                color: BRAND_DARK, fontWeight: 800, fontSize: 13, flexShrink: 0
                            }}
                        >
                            {name.slice(0, 1)}
                        </Avatar>
                    )}
                    <Box>
                        <Typography variant="body2" sx={{ fontWeight: 700, color: BRAND_DARK }}>{name}</Typography>
                        <Typography variant="caption" color="textSecondary">{sub}</Typography>
                    </Box>
                </Stack>
                <Typography variant="caption" color="textSecondary">{pct}%</Typography>
            </Stack>

            <LinearProgress
                variant="determinate"
                value={pct}
                sx={{
                    mt: 0.75, height: 6, borderRadius: 999,
                    bgcolor: "rgba(0,0,0,0.06)",
                    "& .MuiLinearProgress-bar": { bgcolor: barColor }
                }}
            />
        </Box>
    );
}

function TimelineItem({ date, title, desc, isLast, state }) {
    const dotColor = state === "done" ? "#2e7d32" : state === "active" ? BRAND_PRIMARY : "rgba(0,0,0,0.28)";
    return (
        <Stack direction="row" spacing={2}>
            <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                <Box sx={{ width: 10, height: 10, borderRadius: "50%", bgcolor: dotColor, mt: 0.5 }} />
                {!isLast && <Box sx={{ width: 2, flex: 1, bgcolor: "rgba(0,0,0,0.12)", my: 1 }} />}
            </Box>
            <Box sx={{ pb: isLast ? 0 : 2.25, flex: 1 }}>
                <Chip size="small" label={date} sx={{ bgcolor: "rgba(0,0,0,0.04)", "& .MuiChip-label": { fontWeight: 700 } }} />
                <Typography variant="subtitle1" sx={{ mt: 0.75, fontWeight: 800, color: BRAND_DARK }}>{title}</Typography>
                <Typography variant="body2" color="textSecondary" sx={{ mt: 0.25 }}>{desc}</Typography>
            </Box>
        </Stack>
    );
}

function EcosystemItem({ name, sub, href }) {
    return (
        <Stack
            direction="row"
            alignItems="center"
            spacing={1.25}
            sx={{ py: 1, "&:not(:last-of-type)": { borderBottom: "1px dashed rgba(0,0,0,0.08)" } }}
        >
            <Avatar
                sx={{
                    width: 28, height: 28, bgcolor: "rgba(169,120,85,0.12)",
                    color: BRAND_PRIMARY, fontWeight: 800, fontSize: 13, flexShrink: 0
                }}
            >
                {name.slice(0, 1)}
            </Avatar>
            <Box sx={{ flex: 1, minWidth: 0 }}>
                <Typography variant="body2" sx={{ fontWeight: 700, color: BRAND_DARK, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {name}
                </Typography>
                <Typography variant="caption" color="textSecondary" sx={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {sub}
                </Typography>
            </Box>
            <Button
                component="a"
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                size="small"
                variant="text"
                sx={{ textTransform: "none", minWidth: 0, px: 0.5, color: BRAND_PRIMARY, fontWeight: 700 }}
            >
                View
            </Button>
        </Stack>
    );
}

export default function RoadToMainnet() {
    // derive Beta progress from coreDev average
    const betaProgress = coreDev.length
        ? coreDev.reduce((sum, it) => sum + (Number(it.pct) || 0), 0) / coreDev.length
        : 0;

    return (
        <Box sx={{ py: 10, bgcolor: "white" }} id="roadtomainnet">
            <Container maxWidth="lg">
                <Grid container spacing={5} alignItems="center" justifyContent="center">
                    {/* LEFT */}
                    <Grid item xs={12} md={6}>
                        <Box sx={{ backgroundColor: "rgba(208,233,239,0.5)", color: BRAND_BLUE, px: 3, py: 1, borderRadius: "20px", fontSize: 14, textTransform: "uppercase", mb: 2, display: "inline-block" }}>
                            Road to Mainnet
                        </Box>

                        <Typography variant="h4" component="h2" sx={{ fontWeight: "bold", mb: 1.25, color: "#333" }}>
                            Afina Beta → Mainnet
                        </Typography>

                        <Typography variant="body1" color="textSecondary" sx={{ mb: 2.25, lineHeight: 1.7 }}>
                            We’re in <b>Afina Testnet (Beta)</b> for <b>7 months from June 28, 2025</b>. Build and test on Afina.
                            Contributors earn <b>RPU</b> on testnet; RPUs will <b>migrate to mainnet</b>. App data may also migrate at each developer’s discretion.
                        </Typography>

                        <Stack direction="row" spacing={1} sx={{ mb: 2, flexWrap: "wrap" }}>
                            <StatPill label="Beta ends Jan 28, 2026" />
                            <StatPill label="Mainnet target: Mar 2026" />
                            <StatPill label="RPU → Mainnet: Yes" />
                        </Stack>

                        <Box sx={{ mb: 3 }}>
                            <Typography variant="caption" color="textSecondary" sx={{ mb: 0.75, display: "block" }}>
                                Beta progress
                            </Typography>
                            <LinearProgress
                                variant="determinate"
                                value={betaProgress}
                                sx={{
                                    height: 10, borderRadius: 999, bgcolor: "rgba(0,0,0,0.06)",
                                    "& .MuiLinearProgress-bar": { bgcolor: BRAND_PRIMARY }
                                }}
                            />
                            <Typography variant="caption" sx={{ mt: 0.75, display: "block", color: "#666" }}>
                                {Math.round(betaProgress)}%
                            </Typography>
                        </Box>

                        <Box sx={{ borderLeft: "1px solid rgba(0,0,0,0.08)", pl: 2, ml: 1, mb: 3 }}>
                            {milestones.map((m, i) => (
                                <TimelineItem key={m.title} date={m.date} title={m.title} desc={m.desc} state={m.state} isLast={i === milestones.length - 1} />
                            ))}
                        </Box>
                    </Grid>

                    {/* RIGHT */}
                    <Grid item xs={12} md={5}>
                        <Stack spacing={2.5}>
                            {/* Core Development */}
                            <Card elevation={0} sx={{ borderRadius: 2, border: "1px solid rgba(0,0,0,0.08)" }}>
                                <CardContent>
                                    <Typography variant="subtitle2" sx={{ color: BRAND_PRIMARY, fontWeight: 800, mb: 1 }}>
                                        Core Development (Snapshot)
                                    </Typography>
                                    {coreDev.map((c) => (
                                        <ProgressRow key={c.name} name={c.name} sub={c.sub} pct={c.pct} />
                                    ))}
                                </CardContent>
                            </Card>

                            {/* Ecosystem Apps */}
                            <Card elevation={0} sx={{ borderRadius: 2, border: "1px solid rgba(0,0,0,0.08)" }}>
                                <CardContent>
                                    <Typography variant="subtitle2" sx={{ color: BRAND_PRIMARY, fontWeight: 800 }}>
                                        Ecosystem Apps
                                    </Typography>

                                    <Typography variant="caption" color="textSecondary" sx={{ display: "block", mt: 0.5, mb: 1 }}>
                                        Alkebueleum Technology LLC Apps
                                    </Typography>
                                    <Box sx={{ mb: 1.5 }}>
                                        {alkebApps.map((a) => (
                                            <ProgressRow key={a.name} name={a.name} sub={a.sub} pct={a.pct} showAvatar />
                                        ))}
                                    </Box>

                                    <Typography variant="caption" color="textSecondary" sx={{ display: "block", mb: 1 }}>
                                        Built by independent teams on Alkebuleum
                                    </Typography>
                                    <Stack spacing={0}>
                                        {ecosystemApps.map((e) => (
                                            <EcosystemItem key={e.name} {...e} />
                                        ))}
                                    </Stack>

                                    <Box sx={{ mt: 1.5 }}>
                                        <Button
                                            component="a"
                                            href="#buildonalkebuleum"
                                            variant="outlined"
                                            endIcon={<ArrowForwardIcon />}
                                            sx={{
                                                borderColor: BRAND_PRIMARY, color: BRAND_PRIMARY, textTransform: "none",
                                                borderRadius: "10px", px: 2, "&:hover": { backgroundColor: "#f9d0ba", borderColor: "#f9d0ba", color: "#333" },
                                            }}
                                        >
                                            Build on Alkebuleum — Get Started
                                        </Button>
                                    </Box>
                                </CardContent>
                            </Card>
                        </Stack>
                    </Grid>
                </Grid>
            </Container>
        </Box>
    );
}
