import React from "react";
import {
    Box,
    Container,
    Grid,
    Card,
    CardContent,
    Typography,
    Chip,
    useTheme,
    Button,
} from "@mui/material";
import SchoolIcon from "@mui/icons-material/School";
import PersonAddIcon from "@mui/icons-material/PersonAdd";
import CodeIcon from "@mui/icons-material/Code";
import BarChartIcon from "@mui/icons-material/BarChart";
import howItWorksArt from "../../images/howItWorksArt.png";

const steps = [
    {
        icon: PersonAddIcon,
        title: "Get a ZKID",
        description: "Register your decentralized identity in minutes—no central gatekeeper.",
        action: {
            label: "Go to Mahcoin.org",
            link: "https://mahcoin.org",
            external: true,
        },
    },
    {
        icon: SchoolIcon,
        title: "Get Educated",
        description: "Learn blockchain fundamentals and Alkebuleum through our Academy.",
        action: {
            label: "Go to Learn",
            link: "#academy",
        },
    },
    {
        icon: CodeIcon,
        title: "Deploy Your Solution",
        description: "Launch smart-contract templates (e.g. land registry, audit trail) with one click.",
        action: {
            label: "Go to Developer",
            link: "#buildonalkebuleum",
        },
    },
    {
        icon: BarChartIcon,
        title: "Monitor & Govern",
        description: "Use our dashboard for real-time transparency, voting, and reporting.",
    },
];

export default function HowItWorksSection() {
    const theme = useTheme();

    return (
        <Box
            component="section"
            id="howitworks"
            sx={{
                py: { xs: 10, md: 14 },
                bgcolor: "#FAFAF8",
            }}
        >
            <Container maxWidth="lg">
                <Grid container spacing={6} alignItems="center">
                    {/* Image */}
                    <Grid item xs={12} md={6}>
                        <Box
                            component="img"
                            src={howItWorksArt}
                            alt="How It Works Illustration"
                            sx={{
                                width: "100%",
                                height: "auto",
                                borderRadius: "16px",
                                boxShadow: "0px 8px 24px rgba(0, 0, 0, 0.08)",
                            }}
                        />
                    </Grid>

                    {/* Steps */}
                    <Grid item xs={12} md={6}>
                        <Box textAlign={{ xs: "center", md: "left" }} mb={6}>
                            <Chip
                                label="How It Works"
                                sx={{
                                    mb: 2,
                                    backgroundColor: "rgba(208, 233, 239, 0.5)",
                                    color: "#7BA6AC",
                                    fontWeight: "bold",
                                    textTransform: "uppercase",
                                    px: 2,
                                    py: 0.5,
                                    fontSize: "14px",
                                    borderRadius: "20px",
                                }}
                            />
                            <Typography
                                variant="h4"
                                component="h2"
                                fontWeight="bold"
                                mb={3}
                                color="#333"
                            >
                                Get Started with Four Simple Steps
                            </Typography>
                            <Typography
                                variant="body1"
                                color="textSecondary"
                                sx={{ lineHeight: 1.7, maxWidth: 500, mx: { xs: "auto", md: "0" } }}
                            >
                                Follow these steps to start building on Alkebuleum—no deep tech skills required.
                            </Typography>
                        </Box>

                        {/* Step Cards */}
                        <Grid container spacing={3}>
                            {steps.map(({ icon: Icon, title, description, action }, idx) => (
                                <Grid item xs={12} sm={6} key={idx}>
                                    <Card
                                        elevation={0}
                                        sx={{
                                            border: "1px solid #D0E9EF",
                                            borderRadius: 3,
                                            p: 3,
                                            textAlign: "center",
                                            height: "100%",
                                            backgroundColor: "#fff",
                                            transition: "all 0.3s ease",
                                            "&:hover": {
                                                transform: "translateY(-4px)",
                                                boxShadow: "0px 8px 20px rgba(0, 0, 0, 0.08)",
                                            },
                                        }}
                                    >
                                        <Box mb={2} display="flex" justifyContent="center">
                                            <Icon sx={{ fontSize: 40, color: "#2C3E50" }} />
                                        </Box>
                                        <CardContent>
                                            <Typography variant="h6" fontWeight="bold" gutterBottom>
                                                {title}
                                            </Typography>
                                            <Typography
                                                variant="body2"
                                                color="text.secondary"
                                                sx={{ lineHeight: 1.7, mb: 2 }}
                                            >
                                                {description}
                                            </Typography>

                                            {action && (
                                                <Button
                                                    variant="outlined"
                                                    fullWidth
                                                    component="a"
                                                    href={action.link}
                                                    target={action.external ? "_blank" : undefined}
                                                    rel={action.external ? "noopener noreferrer" : undefined}
                                                    sx={{
                                                        textTransform: "none",
                                                        fontWeight: "bold",
                                                        borderColor: "#A97855",
                                                        color: "#A97855",
                                                        "&:hover": {
                                                            backgroundColor: "#f9d0ba",
                                                            borderColor: "#f9d0ba",
                                                            color: "#333",
                                                        },
                                                    }}
                                                >
                                                    {action.label}
                                                </Button>
                                            )}
                                        </CardContent>
                                    </Card>
                                </Grid>
                            ))}
                        </Grid>
                    </Grid>
                </Grid>
            </Container>
        </Box>
    );
}
